"use client";

import * as React from "react";
import {
	DndContext,
	type DragEndEvent,
	KeyboardSensor,
	PointerSensor,
	closestCorners,
	useSensor,
	useSensors,
} from "@dnd-kit/core";
import {
	SortableContext,
	sortableKeyboardCoordinates,
	useSortable,
	verticalListSortingStrategy,
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { cn } from "../../lib/utils.js";

/**
 * Headless Kanban board backed by @dnd-kit. Cards drag within their column
 * (reorder) and across columns (move). Consumer keeps state shape:
 *
 *   columns: Array<{ id: string; title: string; cardIds: string[] }>
 *
 * Kanban receives that array + an `onChange(next)` callback, computes the
 * new state on drop, and fires the callback. No internal state. Card
 * content is fully consumer-rendered — pass any children to `<KanbanCard>`.
 *
 * Columns are static in v1 (no column reorder; cards are the moving parts).
 *
 * Heavy peer: `@dnd-kit/core` + `@dnd-kit/sortable` (~40 KB gzip). Shipped
 * via the hex-core CLI's heavy-peer prompt.
 *
 * @example
 * const [board, setBoard] = useState([
 *   { id: "todo", title: "To do", cardIds: ["1", "2"] },
 *   { id: "doing", title: "Doing", cardIds: ["3"] },
 *   { id: "done", title: "Done", cardIds: [] },
 * ]);
 * const cards = { "1": "Wire DnD", "2": "Build Kanban", "3": "Ship PR" };
 *
 * <Kanban columns={board} onChange={setBoard}>
 *   {board.map((col) => (
 *     <KanbanColumn key={col.id} id={col.id} title={col.title}>
 *       {col.cardIds.map((cardId) => (
 *         <KanbanCard key={cardId} id={cardId}>
 *           {cards[cardId]}
 *         </KanbanCard>
 *       ))}
 *     </KanbanColumn>
 *   ))}
 * </Kanban>
 */

export interface KanbanColumnData {
	id: string;
	title: string;
	cardIds: string[];
}

export interface KanbanProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "children" | "onChange"> {
	columns: KanbanColumnData[];
	/** Called with the next columns array after a drop. */
	onChange: (next: KanbanColumnData[]) => void;
	/** Render the columns. Use `<KanbanColumn>` + `<KanbanCard>` inside. */
	children: React.ReactNode;
}

interface KanbanContextValue {
	columns: KanbanColumnData[];
}

const KanbanContext = React.createContext<KanbanContextValue | null>(null);

function useKanbanContext(): KanbanContextValue {
	const ctx = React.useContext(KanbanContext);
	if (!ctx) {
		throw new Error("KanbanColumn / KanbanCard must be rendered inside <Kanban>.");
	}
	return ctx;
}

/**
 * Find which column owns a given card id.
 * Exported for unit testing of the moveCard algorithm.
 */
export function findColumnIdForCard(columns: KanbanColumnData[], cardId: string): string | null {
	for (const col of columns) {
		if (col.cardIds.includes(cardId)) return col.id;
	}
	return null;
}

/**
 * Move a card to a target position. The target can be either another card
 * (insert at that card's index in its column) OR a column itself (append
 * to that column's cardIds).
 * Returns the same `columns` reference (===) when no move is possible — the
 * caller uses identity equality to skip an onChange call.
 * Exported for unit testing.
 */
export function moveCard(
	columns: KanbanColumnData[],
	activeId: string,
	overId: string,
): KanbanColumnData[] {
	const sourceColId = findColumnIdForCard(columns, activeId);
	if (!sourceColId) return columns;

	// Did we drop onto another card or onto a column?
	const overIsColumn = columns.some((c) => c.id === overId);
	const targetColId = overIsColumn ? overId : findColumnIdForCard(columns, overId);
	if (!targetColId) return columns;

	if (sourceColId === targetColId) {
		// Intra-column reorder.
		return columns.map((col) => {
			if (col.id !== sourceColId) return col;
			const oldIndex = col.cardIds.indexOf(activeId);
			const newIndex = overIsColumn ? col.cardIds.length - 1 : col.cardIds.indexOf(overId);
			if (oldIndex === -1 || newIndex === -1 || oldIndex === newIndex) return col;
			const next = [...col.cardIds];
			next.splice(oldIndex, 1);
			next.splice(newIndex, 0, activeId);
			return { ...col, cardIds: next };
		});
	}

	// Cross-column move.
	return columns.map((col) => {
		if (col.id === sourceColId) {
			return { ...col, cardIds: col.cardIds.filter((id) => id !== activeId) };
		}
		if (col.id === targetColId) {
			const insertAt = overIsColumn ? col.cardIds.length : col.cardIds.indexOf(overId);
			const next = [...col.cardIds];
			next.splice(insertAt < 0 ? next.length : insertAt, 0, activeId);
			return { ...col, cardIds: next };
		}
		return col;
	});
}

/**
 * Headless Kanban board root.
 * @param props - columns + onChange + children renderers
 * @returns A flex row of columns inside a DndContext
 */
function Kanban({ columns, onChange, children, className, ...rest }: KanbanProps) {
	const sensors = useSensors(
		useSensor(PointerSensor, {
			activationConstraint: { distance: 4 },
		}),
		useSensor(KeyboardSensor, {
			coordinateGetter: sortableKeyboardCoordinates,
		}),
	);

	const onChangeRef = React.useRef(onChange);
	onChangeRef.current = onChange;

	const handleDragEnd = React.useCallback(
		(event: DragEndEvent) => {
			const { active, over } = event;
			if (!over || active.id === over.id) return;
			const next = moveCard(columns, String(active.id), String(over.id));
			if (next === columns) return;
			onChangeRef.current(next);
		},
		[columns],
	);

	const contextValue = React.useMemo<KanbanContextValue>(() => ({ columns }), [columns]);

	return (
		<KanbanContext.Provider value={contextValue}>
			<DndContext
				sensors={sensors}
				collisionDetection={closestCorners}
				onDragEnd={handleDragEnd}
			>
				<div
					{...rest}
					data-hex-kanban
					className={cn("flex gap-4 overflow-x-auto", className)}
				>
					{children}
				</div>
			</DndContext>
		</KanbanContext.Provider>
	);
}

export interface KanbanColumnProps
	extends Omit<React.HTMLAttributes<HTMLDivElement>, "children" | "title"> {
	id: string;
	title: React.ReactNode;
	children?: React.ReactNode;
}

/**
 * Single Kanban column. Provides a SortableContext for its cards and
 * registers itself as a drop target so empty columns still accept cards.
 * @param props - column id + visible title + KanbanCard children
 */
function KanbanColumn({ id, title, children, className, ...rest }: KanbanColumnProps) {
	const { columns } = useKanbanContext();
	const col = columns.find((c) => c.id === id);
	const cardIds = col?.cardIds ?? [];
	// Make the column droppable too (so dropping onto an empty column works).
	const { setNodeRef } = useSortable({ id });

	return (
		<div
			{...rest}
			ref={setNodeRef}
			data-hex-kanban-column
			data-column-id={id}
			className={cn(
				"flex w-72 shrink-0 flex-col gap-2 rounded-lg border bg-muted/30 p-3",
				className,
			)}
		>
			<header className="text-sm font-medium text-muted-foreground">{title}</header>
			<SortableContext items={cardIds} strategy={verticalListSortingStrategy}>
				<div className="flex min-h-[2rem] flex-col gap-2">{children}</div>
			</SortableContext>
		</div>
	);
}

export interface KanbanCardProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "children"> {
	id: string;
	children: React.ReactNode;
}

/**
 * Single sortable Kanban card. Spreads attributes + listeners onto a
 * draggable wrapper. Children are fully consumer-rendered — pass a
 * `<Card>` or any custom layout.
 * @param props - card id + children content
 */
function KanbanCard({ id, children, className, ...rest }: KanbanCardProps) {
	const { setNodeRef, attributes, listeners, transform, transition, isDragging } = useSortable({
		id,
	});

	const style: React.CSSProperties = {
		transform: CSS.Transform.toString(transform),
		transition,
		opacity: isDragging ? 0.5 : 1,
	};

	return (
		<div
			{...rest}
			ref={setNodeRef}
			style={style}
			{...attributes}
			{...listeners}
			data-hex-kanban-card
			data-card-id={id}
			data-dragging={isDragging}
			className={cn(
				"cursor-grab rounded-md border bg-background p-3 text-sm shadow-sm",
				"hover:bg-accent/50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
				"active:cursor-grabbing",
				className,
			)}
		>
			{children}
		</div>
	);
}

export { Kanban, KanbanColumn, KanbanCard };

/**
 * Color conversion utilities for the HSL-triplet token format used across
 * `@hex-core/tokens` themes (`H S% L%`, e.g. `"240 5.9% 10%"` — no `hsl()`
 * wrapper, no commas).
 *
 * The triplet is the round-trip-safe serialization for Hex Core: tokens flow
 * triplet → CSS `hsl(var(--token))` → rendered color, and the ColorPicker
 * component edits triplets directly. Hex/RGB conversions are display
 * adapters, not the source of truth.
 */

/** Parsed HSL components. `h` is degrees (0–360); `s` and `l` are percentages (0–100). */
export interface HslTriplet {
	h: number;
	s: number;
	l: number;
}

/** Parsed RGB components. Each channel is 0–255. */
export interface RgbColor {
	r: number;
	g: number;
	b: number;
}

/**
 * Parse an HSL triplet string into numeric components.
 *
 * Note: malformed input silently coerces to `{0,0,0}` (pure black) rather than
 * returning an error signal. Callers that need to distinguish "user typed
 * black" from "user typed garbage" should validate the input format first.
 * `hexToHslTriplet` returns `null` for malformed hex; this asymmetry is
 * intentional — triplets feed CSS variables where any non-color value would
 * already break rendering.
 *
 * @param triplet - String in the form `"<H> <S>% <L>%"` (e.g. `"240 5.9% 10%"`).
 * @returns Numeric components, or `{0,0,0}` if the input is malformed.
 */
export function parseHslTriplet(triplet: string): HslTriplet {
	const parts = triplet.trim().split(/\s+/);
	return {
		h: Number.parseFloat(parts[0]) || 0,
		s: Number.parseFloat(parts[1]) || 0,
		l: Number.parseFloat(parts[2]) || 0,
	};
}

/**
 * Format HSL components into an HSL triplet string (the canonical token format).
 * @param hsl - Numeric components.
 * @returns Triplet in the form `"<H> <S>% <L>%"`.
 */
export function formatHslTriplet({ h, s, l }: HslTriplet): string {
	// Tolerant integer check: rgbToHsl can produce values like 5.0000000001 due
	// to float arithmetic; format those as "5" rather than "5.0".
	const round = (n: number) =>
		Math.abs(n - Math.round(n)) < 1e-6 ? `${Math.round(n)}` : n.toFixed(1);
	return `${Math.round(h)} ${round(s)}% ${round(l)}%`;
}

/**
 * Convert HSL components to RGB.
 * @param h - Hue (0–360).
 * @param s - Saturation (0–100).
 * @param l - Lightness (0–100).
 * @returns RGB channels (0–255, rounded).
 */
export function hslToRgb(h: number, s: number, l: number): RgbColor {
	const sN = s / 100;
	const lN = l / 100;
	const k = (n: number) => (n + h / 30) % 12;
	const a = sN * Math.min(lN, 1 - lN);
	const f = (n: number) => lN - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
	return {
		r: Math.round(255 * f(0)),
		g: Math.round(255 * f(8)),
		b: Math.round(255 * f(4)),
	};
}

/**
 * Convert RGB components to HSL.
 * @param r - Red (0–255).
 * @param g - Green (0–255).
 * @param b - Blue (0–255).
 * @returns HSL components (h: 0–360, s: 0–100, l: 0–100).
 */
export function rgbToHsl(r: number, g: number, b: number): HslTriplet {
	const rN = r / 255;
	const gN = g / 255;
	const bN = b / 255;
	const max = Math.max(rN, gN, bN);
	const min = Math.min(rN, gN, bN);
	let h = 0;
	let s = 0;
	const l = (max + min) / 2;
	if (max !== min) {
		const d = max - min;
		s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
		if (max === rN) h = (gN - bN) / d + (gN < bN ? 6 : 0);
		else if (max === gN) h = (bN - rN) / d + 2;
		else h = (rN - gN) / d + 4;
		h /= 6;
	}
	return { h: h * 360, s: s * 100, l: l * 100 };
}

/**
 * Convert an HSL triplet to a 6-digit hex string.
 * @param triplet - HSL triplet (e.g. `"240 5.9% 10%"`).
 * @returns Lowercase hex string with leading `#` (e.g. `"#181a1f"`).
 */
export function hslTripletToHex(triplet: string): string {
	const { h, s, l } = parseHslTriplet(triplet);
	const { r, g, b } = hslToRgb(h, s, l);
	const toHex = (n: number) => n.toString(16).padStart(2, "0");
	return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

/**
 * Convert a hex string to an HSL triplet.
 * Accepts 3-digit (`#abc`) or 6-digit (`#aabbcc`) hex with optional `#`.
 * @param hex - Hex color string.
 * @returns HSL triplet, or `null` if the input is malformed.
 */
export function hexToHslTriplet(hex: string): string | null {
	const clean = hex.trim().replace(/^#/, "");
	let normalized: string;
	if (/^[0-9a-fA-F]{3}$/.test(clean)) {
		normalized = clean
			.split("")
			.map((c) => c + c)
			.join("");
	} else if (/^[0-9a-fA-F]{6}$/.test(clean)) {
		normalized = clean;
	} else {
		return null;
	}
	const r = Number.parseInt(normalized.slice(0, 2), 16);
	const g = Number.parseInt(normalized.slice(2, 4), 16);
	const b = Number.parseInt(normalized.slice(4, 6), 16);
	return formatHslTriplet(rgbToHsl(r, g, b));
}

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * Merge class names with Tailwind CSS conflict resolution.
 * @param inputs - Class values (strings, arrays, objects) to merge
 * @returns A single merged class string with Tailwind conflicts resolved
 */
export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

const SAFE_URL_SCHEMES = ["http:", "https:", "mailto:"] as const;

/**
 * Allowlist a URL for use as an `<a href>` against untrusted input.
 *
 * Returns the raw string when it's `http(s):` / `mailto:` / a relative
 * URL (no scheme); returns `undefined` otherwise. Defends against
 * `javascript:` / `data:` / `vbscript:` injection from streamed model
 * output or third-party JSON payloads that flow into citation chips.
 *
 * Inside a Markdown render path, `rehype-sanitize` already strips
 * `javascript:` from inline-link hrefs — but it does NOT introspect
 * JSON nested inside attribute values (e.g. `<sources data='[…]'/>`),
 * so the components that consume that data must guard themselves.
 *
 * @param raw - The candidate URL, or `undefined` when none was supplied.
 * @returns The URL when safe to render, otherwise `undefined`.
 */
export function safeUrl(raw: string | undefined): string | undefined {
	if (raw === undefined || raw === "") return undefined;
	// Relative URLs have no scheme — `new URL(relative)` throws without a base,
	// so a thrown URL means either malformed input OR a relative path. Treat
	// "throws + does not contain a colon" as a relative path (safe).
	let parsed: URL;
	try {
		parsed = new URL(raw);
	} catch {
		return raw.includes(":") ? undefined : raw;
	}
	return SAFE_URL_SCHEMES.some((scheme) => scheme === parsed.protocol) ? raw : undefined;
}

